import {colorVariables} from './subject-colors.js';
import {db,save,put,uid,TODAY,course,room,attendanceStats,budgetSummary,flushWorkspace} from './data.js';
export {db,save,put,uid,TODAY,course,room,attendanceStats,budgetSummary};
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 10 2 2 5-5m-7 10h8"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1zm0 0v15"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8h18m0 4h-6v5h6m-3-3h.1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zm5 3h4"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',edit:'<path d="m15 4 5 5M4 20l1-6L16 3l5 5L10 19z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',study:'<path d="m2 9 10-5 10 5-10 5zm4 3v6c4 3 8 3 12 0v-6m4-3v8"/>',logout:'<path d="M10 4H4v16h6m3-12 4 4-4 4m-5-4h13"/>'};
export const icon=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.book}</svg>`;
export const button=(label,table,id='',defaults={})=>`<button class="btn primary" data-form="${table}" data-id="${id}" data-defaults="${esc(JSON.stringify(defaults))}">${icon('plus')}${esc(label)}</button>`;
export const edit=(table,id)=>`<button class="icon-btn" data-form="${table}" data-id="${id}" aria-label="Edit ${table.replaceAll('_',' ')}">${icon('edit')}</button>`;
export const money=(v,c=db.users[0].default_currency_code)=>`${esc(c)} ${Number(v).toLocaleString('en-US',{maximumFractionDigits:0})}`;
export const date=(v,opts={month:'short',day:'numeric'})=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('en-GB',opts):'No date';
export const time=v=>v?new Date(v).toLocaleTimeString('en-GB',{timeZone:db.users[0].timezone,hour:'2-digit',minute:'2-digit'}):'';
export const day=v=>v?new Intl.DateTimeFormat('en-CA',{timeZone:db.users[0].timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v)):'';
export const tag=(s,c='')=>`<span class="tag ${c}">${esc(s)}</span>`;
export const empty=s=>`<div class="empty">${esc(s)}</div>`;
export const heading=(e,t,d,a='')=>`<header class="page-heading"><div><div class="eyebrow">${esc(e)}</div><h1>${esc(t)}</h1><p>${esc(d)}</p></div>${a}</header>`;
export const section=(t,c,l='',s='')=>`<section class="card"><div class="section-head"><div><h2>${t}</h2>${s?`<p>${s}</p>`:''}</div>${l}</div>${c}</section>`;
export const stat=(label,value,note,i='calendar')=>`<article class="card"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><div class="metric">${value}</div><div class="stat-note">${note}</div></article>`;
const nav=[['index','Today','home'],['schedule','Schedule','calendar'],['tasks','Tasks','tasks'],['study','Study','study'],['budget','Budget','wallet'],['info','Campus info','book']];
const secondary=[['courses','Courses','book'],['import','Import timetable','calendar'],['attendance','Attendance','check'],['reminders','Reminders','bell'],['book-appointment','Book appointment','calendar'],['my-appointments','My appointments','calendar'],['settings','Settings','settings']];
export function mount(render){const page=document.body.dataset.page,initials=db.users[0].full_name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase()||'U';document.body.innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="index.html"><span class="brandmark">c</span>campus<span style="color:#2858ee">.</span></a><div class="nav-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([p,t,i])=>`<a href="${p}.html" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}<details class="more-navigation" ${secondary.some(([p])=>p===page)||page==='course'?'open':''}><summary>${icon('menu')}More</summary><div>${secondary.map(([p,t,i])=>`<a href="${p}.html" class="${page===p||(page==='course'&&p==='courses')?'active':''}">${icon(i)}${t}</a>`).join('')}</div></details></nav><div class="sidebar-foot"><div class="help-box"><strong class="small">Make yourself at home.</strong><p>A little setup now makes your week a lot easier.</p><a href="setup.html">Getting started →</a></div><a class="profile" href="settings.html"><span class="avatar">${esc(initials)}</span><div><strong id="profile-name">${esc(db.users[0].full_name)}</strong><small>${esc(window.CampusSession.email||'Your personal workspace')}</small></div></a></div></aside><div class="workspace"><div class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" id="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span>My workspace</span><span>/</span><strong>${esc(document.title.split(' | ')[0])}</strong></div><div class="top-actions"><button id="sign-out" type="button" class="icon-btn" aria-label="Sign out" title="Sign out">${icon('logout')}</button><a class="icon-btn" href="reminders.html" aria-label="View reminders">${icon('bell')}<i class="dot"></i></a><a class="avatar" href="settings.html" aria-label="Profile">${esc(initials)}</a><button class="icon-btn theme-toggle" id="theme-toggle" type="button" role="switch" aria-label="Dark mode" aria-checked="false" title="Switch to dark mode"><svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 13.1A9 9 0 0 1 10.9 3.2 9 9 0 1 0 20.8 13.1Z"/></svg><span class="theme-toggle-label">Dark mode</span></button></div></div><main id="main"></main></div><dialog id="editor"></dialog><div class="toast" id="toast" role="status" aria-live="polite"></div>`;
const update=()=>{document.querySelector('#main').innerHTML=render()+`<footer class="page-footer"><span>A little more organized. A lot more in control.</span><span>Campus</span></footer>`;document.querySelector('#profile-name').textContent=db.users[0].full_name};window.addEventListener('datachange',update);update();window.CampusTheme?.bindToggle();window.addEventListener('workspace-sync-error',()=>toast('Saved on this device. Could not sync with the server; reconnect and try saving again.'));document.querySelector('#sign-out').onclick=async()=>{const b=document.querySelector('#sign-out');b.disabled=true;try{await flushWorkspace();const r=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});if(!r.ok)throw Error();try{localStorage.setItem('campus-signout',String(Date.now()))}catch{}location.replace('login.html')}catch{b.disabled=false;toast('Could not sign out. Please try again.')}};document.querySelector('#menu').onclick=()=>{let open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',open)};
document.addEventListener('click',async e=>{if(innerWidth<=640&&!e.target.closest('.sidebar,#menu')){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}const f=e.target.closest('[data-form]');if(f){let {openForm}=await import('./forms.js');openForm(f.dataset.form,f.dataset.id,JSON.parse(f.dataset.defaults||'{}'))}const b=e.target.closest('[data-complete]');if(b){let t=db.tasks.find(t=>t.id===b.dataset.complete);t.status=t.status==='done'?'todo':'done';t.completed_at=t.status==='done'?new Date().toISOString():null;save();toast(t.status==='done'?'Task completed. Nice work!':'Task reopened.')}const a=e.target.closest('[data-attend]');if(a){let s=db.class_sessions.find(s=>s.id===a.dataset.attend),r=db.attendance.find(r=>r.class_session_id===s.id),{openForm}=await import('./forms.js');openForm('attendance',r?.id,{class_session_id:s.id,status:'present'})}});return update;}
export function toast(m){let t=document.querySelector('#toast');t.textContent=m;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.textContent='',4000)}
export function taskCourse(task){let current=task,seen=new Set();while(current&&!seen.has(current.id)){seen.add(current.id);const subject=course(current.course_id);if(subject)return subject;current=db.tasks.find(t=>t.id===current.parent_task_id)}return null}
export function taskRow(t){const c=taskCourse(t),done=t.status==='done';return `<div class="task-row subject-colored" style="${colorVariables(c?.color)}"><button class="check ${done?'done':''}" data-complete="${t.id}" aria-label="${done?'Reopen':'Complete'} ${esc(t.title)}">${done?icon('check'):''}</button><div class="task-main"><div class="task-heading"><strong class="${done?'completed':''}">${esc(t.title)}</strong><span class="task-subject-label" aria-label="Subject: ${esc(c?.name||'Personal')}">${esc(c?.name||'Personal')}</span></div><div class="task-bottom"><small><span class="course-dot"></span>${esc(c?.course_code||'Personal')} · ${esc(t.task_type)}${t.parent_task_id?' · Subtask':''}</small><div class="task-row-actions">${tag(t.due_at?date(t.due_at):'Unscheduled',t.due_at?.slice(0,10)<=TODAY&&!done?'warn':'')}${edit('tasks',t.id)}</div></div></div></div>`}
export const subjectStyle=id=>colorVariables(course(id)?.color);
export const roomLabel=id=>{let r=room(id);return r?([r.building,r.room_name?'Room '+r.room_name:null].filter(Boolean).join(' · ')):'Room not set'};
export const sessionType=s=>db.schedules.find(x=>x.id===s.schedule_id)?.title||'Class';
export function sessionRow(s,i=0){const c=course(s.course_id),a=db.attendance.find(a=>a.class_session_id===s.id);return `<article class="session"><div class="session-time">${time(s.starts_at)}<small>${time(s.ends_at)}</small></div><div class="session-body subject-colored ${i===0?'featured':''}" style="${colorVariables(c?.color)}"><div class="row"><h3><a href="course.html?id=${c?.id}">${esc(c?.name||'Class')}</a></h3>${tag(c?.course_code||'',i===0?'blue':'')}</div><div class="session-meta"><span>${icon('pin')} ${esc(roomLabel(s.room_id))}</span><span>${icon('clock')} ${time(s.starts_at)}–${time(s.ends_at)}</span>${tag(sessionType(s),sessionType(s)==='Lecture'?'blue':'')}</div><div class="mini-actions"><span class="small muted">${esc(s.status==='cancelled'?'Cancelled':a?'Attendance: '+a.status:c?.professor_name||'Attendance not marked')}</span><div class="actions">${s.status!=='cancelled'?`<button class="btn ${a?'':'soft'}" data-attend="${s.id}">${a?'Edit attendance':'Mark attendance'}</button>`:''}${edit('class_sessions',s.id)}</div></div></div></article>`}
export function budgetCard(){let b=budgetSummary();if(!b.budget)return '<div class="empty">Set your monthly limit to start tracking your spending.</div>'+button('Set monthly budget','monthly_budgets','',{month_start:TODAY.slice(0,7)+'-01'});let p=b.budget?.spending_limit?Math.round(b.spent/b.budget.spending_limit*100):0;return `<div class="budget-hero"><div class="ring" style="--progress:${Math.min(p,100)}%"><div class="ring-inner"><strong>${p}%</strong><small>OF BUDGET USED</small></div></div><div><div class="small muted">You have left</div><div class="budget-number" style="margin-top:8px">${money(b.remaining,b.budget?.currency_code)}</div><div class="legend"><i></i> ${date(TODAY,{month:'long'})} spending</div></div></div><div class="budget-lines"><div>Spent<strong>${money(b.spent,b.budget?.currency_code)}</strong></div><div>Monthly limit<strong>${money(b.budget?.spending_limit||0,b.budget?.currency_code)}</strong></div></div>`}
export function attendanceLines(){return db.courses.map(c=>{let a=attendanceStats(c.id),warn=a.percent!==null&&a.percent<c.minimum_attendance_percent;return `<div class="attendance-line subject-colored" style="${subjectStyle(c.id)}"><div class="row"><a href="course.html?id=${c.id}">${esc(c.course_code)}</a><strong style="color:${warn?'#b98937':'#2858ee'}">${a.percent===null?'—':a.percent+'%'}</strong></div><div class="progress"><i style="width:${a.percent||0}%;${warn?'background:#d1aa64':''}"></i></div><small>${warn?'Below requirement · ':''}Minimum ${c.minimum_attendance_percent}%${a.unmarked?' · '+a.unmarked+' unmarked':''}</small></div>`}).join('')}
